package in.sevasetu.amc.web;
import in.sevasetu.amc.security.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import java.math.*;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController{
 private final JdbcClient db;public OrderController(JdbcClient db){this.db=db;}public record Line(@NotNull UUID catalogItemId,@Min(1)int quantity,@DecimalMin("0")BigDecimal discount){}public record Create(@NotNull UUID customerId,@NotEmpty List<@Valid Line> items,@Pattern(regexp="UPI|CASH|ZERO")String paymentMethod){}public record Created(UUID id,String billNumber,BigDecimal total){}private record Priced(UUID id,String kind,String name,BigDecimal price,Integer months,int qty,BigDecimal discount){}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) @Transactional Created create(@AuthenticationPrincipal CurrentUser u,@Valid @RequestBody Create req){CustomerController.tenant(u);var customerExists=db.sql("select count(*) from amcservice.customers where id=:id and tenant_id=:t").param("id",req.customerId()).param("t",u.tenantId()).query(Integer.class).single()>0;if(!customerExists)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer not found");var priced=new ArrayList<Priced>();for(var line:req.items()){var p=db.sql("select id,'ITEM' kind,name,price,duration_months from amcservice.catalog_items where id=:id and tenant_id=:t and active union all select id,'PACKAGE',name,price,duration_months from amcservice.packages where id=:id and tenant_id=:t and active").param("id",line.catalogItemId()).param("t",u.tenantId()).query((rs,n)->new Priced(rs.getObject("id",UUID.class),rs.getString("kind"),rs.getString("name"),rs.getBigDecimal("price"),rs.getObject("duration_months",Integer.class),line.quantity(),line.discount()==null?BigDecimal.ZERO:line.discount())).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Catalog item is unavailable"));if(p.discount().compareTo(p.price())>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Discount cannot exceed item price");priced.add(p);}var subtotal=priced.stream().map(p->p.price().multiply(BigDecimal.valueOf(p.qty()))).reduce(BigDecimal.ZERO,BigDecimal::add);var discount=priced.stream().map(p->p.discount().multiply(BigDecimal.valueOf(p.qty()))).reduce(BigDecimal.ZERO,BigDecimal::add);var total="ZERO".equals(req.paymentMethod())?BigDecimal.ZERO:subtotal.subtract(discount).max(BigDecimal.ZERO);var orderId=UUID.randomUUID();var seq=db.sql("select nextval('amcservice.bill_number_seq')").query(Long.class).single();var bill="AMC-"+LocalDate.now().getYear()+"-"+seq;db.sql("insert into amcservice.orders(id,tenant_id,branch_id,customer_id,bill_number,subtotal,discount,total,payment_method,created_by) values(:id,:t,(select branch_id from amcservice.users where id=:user),:c,:bill,:sub,:disc,:total,:method,:user)").param("id",orderId).param("t",u.tenantId()).param("c",req.customerId()).param("bill",bill).param("sub",subtotal).param("disc",discount).param("total",total).param("method",req.paymentMethod()).param("user",u.userId()).update();for(var p:priced){var itemId=UUID.randomUUID();db.sql("insert into amcservice.order_items(id,order_id,item_kind,item_id,description,unit_price,quantity,discount,duration_months,service_expires_on) values(:id,:order,:kind,:item,:name,:price,:qty,:discount,:months,:expiry)").param("id",itemId).param("order",orderId).param("kind",p.kind()).param("item",p.id()).param("name",p.name()).param("price",p.price()).param("qty",p.qty()).param("discount",p.discount()).param("months",p.months()).param("expiry",p.months()==null?null:LocalDate.now().plusMonths(p.months())).update();}db.sql("update amcservice.customers set lifetime_value=lifetime_value+:total where id=:id and tenant_id=:t").param("total",total).param("id",req.customerId()).param("t",u.tenantId()).update();db.sql("insert into amcservice.audit_logs(tenant_id,actor_user_id,action,entity_type,entity_id,details) values(:t,:u,'CREATE','ORDER',:id,jsonb_build_object('bill',:bill))").param("t",u.tenantId()).param("u",u.userId()).param("id",orderId.toString()).param("bill",bill).update();return new Created(orderId,bill,total);}
 @GetMapping List<Map<String,Object>> list(@AuthenticationPrincipal CurrentUser u){var base="select o.id,o.bill_number,o.total,o.payment_method,o.created_at,c.name customer_name,t.name tenant_name,b.name branch_name,(select count(*) from amcservice.order_reference_images ri where ri.order_id=o.id) reference_image_count from amcservice.orders o join amcservice.customers c on c.id=o.customer_id join amcservice.tenants t on t.id=o.tenant_id left join amcservice.branches b on b.id=o.branch_id ";if("ADMIN".equals(u.role()))return db.sql(base+"order by o.created_at desc limit 250").query().listOfRows();CustomerController.tenant(u);return db.sql(base+"where o.tenant_id=:t order by o.created_at desc limit 100").param("t",u.tenantId()).query().listOfRows();}
 @PostMapping(value="/{id}/reference-images",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED) void images(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id,@RequestPart("files")List<MultipartFile> files)throws Exception{CustomerController.tenant(u);var exists=db.sql("select count(*) from amcservice.orders where id=:id and tenant_id=:t").param("id",id).param("t",u.tenantId()).query(Integer.class).single()>0;if(!exists)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Bill not found");if(files.isEmpty()||files.size()>10)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Upload between 1 and 10 images");for(var file:files){if(file.getContentType()==null||!file.getContentType().startsWith("image/")||file.getSize()>5_000_000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Each reference must be an image under 5 MB");db.sql("insert into amcservice.order_reference_images(id,tenant_id,order_id,file_name,content_type,file_size,image_data,uploaded_by) values(:id,:t,:o,:name,:type,:size,:data,:u)").param("id",UUID.randomUUID()).param("t",u.tenantId()).param("o",id).param("name",Optional.ofNullable(file.getOriginalFilename()).orElse("reference")).param("type",file.getContentType()).param("size",file.getSize()).param("data",file.getBytes()).param("u",u.userId()).update();}}
 public record ImageInfo(UUID id,String fileName,String contentType,long fileSize){}
 @GetMapping("/{id}/reference-images") List<ImageInfo> imageList(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id){CustomerController.tenant(u);return db.sql("select id,file_name,content_type,file_size from amcservice.order_reference_images where tenant_id=:t and order_id=:o order by created_at").param("t",u.tenantId()).param("o",id).query(ImageInfo.class).list();}
 @GetMapping("/{orderId}/reference-images/{imageId}") ResponseEntity<byte[]> image(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID orderId,@PathVariable UUID imageId){CustomerController.tenant(u);return db.sql("select content_type,image_data from amcservice.order_reference_images where id=:id and order_id=:o and tenant_id=:t").param("id",imageId).param("o",orderId).param("t",u.tenantId()).query((rs,n)->ResponseEntity.ok().contentType(MediaType.parseMediaType(rs.getString(1))).cacheControl(CacheControl.noStore()).body(rs.getBytes(2))).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Image not found"));}
 public record Correction(@NotNull @DecimalMin("0")BigDecimal total,@Pattern(regexp="UPI|CASH|ZERO")String paymentMethod,@NotBlank String reason){}
 @PatchMapping("/{id}") @org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMIN')") @Transactional void correct(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id,@Valid @RequestBody Correction correction){var changed=db.sql("update amcservice.orders set total=:total,payment_method=:method,updated_at=now() where id=:id").param("total",correction.total()).param("method",correction.paymentMethod()).param("id",id).update();if(changed==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Bill not found");db.sql("insert into amcservice.audit_logs(actor_user_id,action,entity_type,entity_id,details) values(:u,'ADMIN_CORRECTION','ORDER',:id,jsonb_build_object('reason',:reason,'total',:total,'paymentMethod',:method))").param("u",u.userId()).param("id",id.toString()).param("reason",correction.reason()).param("total",correction.total()).param("method",correction.paymentMethod()).update();}
}
